// SPDX-License-Identifier: MIT. Fake GET/SET delegates only; no native transport.
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;

public static class GearLinkHeadsetLightingTests
{
    static int checks;
    static void Check(bool good,string label){if(!good)throw new Exception(label);checks++;}
    static void Reject(Action action,string label){bool rejected=false;try{action();}catch(ArgumentException){rejected=true;}catch(IOException){rejected=true;}Check(rejected,label);}
    static Dictionary<string,object> O(params object[] fields){return GearLinkWorker.Obj(fields);}
    static Dictionary<string,object> Value(int brightness=80,int[] color=null){return O("color",color??new[]{10,20,30},"brightness",brightness);}
    static Dictionary<string,object> Snapshot(Dictionary<string,object> s){return (Dictionary<string,object>)s["snapshot"];}
    sealed class Fake
    {
        internal GearDescriptor Device=new GearDescriptor{Id="hid-0123456789abcdef",Pid=7489,Page=0xFF00,Usage=1,InputLength=65,OutputLength=65,InputReports=new byte[]{0xCC},OutputReports=new byte[]{0xCC}};
        internal int Awake=1,Mode,Brightness=50,Led,Aura,FailStep=-1,RejectStep=-1,ThrowStep=-1;internal int[] Rgb={82,0,111};internal bool NoAck,WrongColor,WrongBrightness,WrongMode,DisableLed,ChangeOwner,ChangeRecipeAtEnable,Disconnect,SwapIdentity,MutateRequest;internal string Missing;internal int ShortLength=-1;internal object Request;
        internal readonly List<byte[]> Queries=new List<byte[]>(),Writes=new List<byte[]>();
        internal byte[] Query(byte[] p){Queries.Add((byte[])p.Clone());if(!GearLinkWorker.IsHeadsetLightingQuery(p))throw new Exception("Fake received an unrelated query.");string field=p[1]==0?"awake":p[1]==3?"lighting":p[1]==19?"lightingEnabled":"auraEnabled";if(Missing==field)throw new IOException("Synthetic missing "+field);byte[] b=new byte[p[1]==3?9:5];Array.Copy(p,b,4);b[4]=(byte)(p[1]==0?(Disconnect&&Writes.Count>0?0:Awake):p[1]==3?Mode:p[1]==19?Led:Aura);if(p[1]==3){b[5]=(byte)Brightness;for(int i=0;i<3;i++)b[6+i]=(byte)Rgb[i];}if(ShortLength>=0&&field=="lighting")Array.Resize(ref b,ShortLength);return b;}
        internal Dictionary<string,object> Read(){var result=GearLinkWorker.ReadHeadsetLightingScope(Device,Query);if(SwapIdentity&&Writes.Count>0)result["deviceId"]="hid-fedcba9876543210";return result;}
        internal GearLinkWorker.SettingReceipt Write(byte[] p){int index=Writes.Count;Writes.Add((byte[])p.Clone());if(index==ThrowStep)throw new IOException("Synthetic output uncertainty.");var receipt=new GearLinkWorker.SettingReceipt{OutputCompleted=index!=FailStep,Acknowledged=!NoAck,Rejected=index==RejectStep};if(!receipt.OutputCompleted||receipt.Rejected)return receipt;
            if(p.Length==5){Led=p[4];if(ChangeRecipeAtEnable)Brightness++;}else {Mode=p[4];Brightness=p[5];Rgb=p.Skip(6).Take(3).Select(v=>(int)v).ToArray();if(WrongMode)Mode=0;if(WrongBrightness)Brightness++;if(WrongColor)Rgb[0]=(Rgb[0]+1)%256;}
            if(DisableLed)Led=0;if(ChangeOwner)Aura=1;if(MutateRequest){var request=Request as Dictionary<string,object>;if(request!=null){request["brightness"]=0;request["color"]=new[]{0,0,0};}}return receipt;
        }
    }
    static Dictionary<string,object> Apply(Fake fake,object value=null,bool noOp=false,Func<int> elapsed=null){return GearLinkWorker.ApplyHeadsetStaticLighting(fake.Device,value??Value(),noOp,fake.Read,fake.Write,elapsed);}
    public static int Main(){try{Run();Console.WriteLine("Headset compound lighting: "+checks+" pure checks; HID/native/real GET/SET=0.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
    static void Run(){
        foreach(int mode in Enumerable.Range(0,6))foreach(int led in new[]{0,1})foreach(int brightness in new[]{0,50,100}){
            var f=new Fake{Mode=mode,Led=led,Brightness=brightness};var before=f.Read();var s=Snapshot(before);Check((bool)before["online"]&&(bool)s["headsetLightingFieldsConfirmed"]&&(bool)s["uniformStaticLightingProtocolAvailable"],"complete raw bytes are prepared independently of enabled state");Check(!(bool)s["headsetLightingHardwareVerified"],"no synthetic hardware verification claim");Check(((string[])before["setCapabilities"]).SequenceEqual(new[]{"staticLighting"}),"minimum setter only");Check(f.Queries.Count==4&&f.Queries[0].SequenceEqual(new byte[]{18,0,0,1}),"four exact GETs with native awake index");
            var plan=GearLinkWorker.BuildHeadsetStaticPlan(Value(),s);Check(plan.Length==(led==0?2:1),"explicit LED bootstrap when needed");Check(plan.Last().Packet.SequenceEqual(new byte[]{81,40,0,0,1,80,10,20,30}),"complete Static1 packet bytes");if(led==0)Check(plan[0].Packet.SequenceEqual(new byte[]{81,16,0,0,1}),"explicit LED packet bytes");
            var bytes=plan.Last().Packet;bytes[4]=5;Check(plan.Last().Packet[4]==1,"plan packet cloning");var applied=Apply(f);Check((bool)applied["writeConfirmed"]&&GearLinkWorker.Text(applied,"appliedState")=="confirmed","all steps fully confirmed");Check(GearLinkWorker.MatchesHeadsetStaticLighting(Value(),Snapshot(applied)),"all LED/Aura/recipe fields read back");Check(f.Writes.Count==(led==0?2:1),"only necessary bounded outputs");Check(!f.Writes.Any(p=>p[1]==51),"never writes Aura ownership");if(mode==0)Check((int)s["lightingEffectCode"]==0&&(bool)s["lightingModeMappingUnconfirmed"],"raw0 observation not converted by planning");
        }
        foreach(string missing in new[]{"awake","lighting","lightingEnabled","auraEnabled"}){var f=new Fake{Missing=missing};var state=f.Read();Check(((string[])state["setCapabilities"]).Length==0&&!(bool)Snapshot(state)["uniformStaticLightingProtocolAvailable"],"missing getter blocks static");Reject(()=>Apply(f),"all current fields required");Check(f.Writes.Count==0,"missing never writes");}
        foreach(var f in new[]{new Fake{Aura=1},new Fake{Aura=2},new Fake{Led=2},new Fake{Mode=6},new Fake{Mode=255},new Fake{Brightness=101},new Fake{Brightness=255},new Fake{Awake=0},new Fake{Awake=2},new Fake{ShortLength=8}}){Reject(()=>Apply(f),"strict original bytes or owner unknown");Check(f.Writes.Count==0,"invalid original no output");}
        foreach(object brightness in new object[]{null,true,"50",50.0,50.5,-1,101,(long)50}){var f=new Fake();var v=Value();v["brightness"]=brightness;Reject(()=>Apply(f,v),"strict static brightness schema");Check(f.Queries.Count==0&&f.Writes.Count==0,"schema validates before first getter");}
        foreach(object rgb in new object[]{null,"RGB",new[]{1,2},new[]{1,2,3,4},new[]{-1,2,3},new[]{1,256,3},new object[]{1,true,3},new object[]{1,2.0,3},O("r",1,"g",2,"b",3)}){var f=new Fake();Reject(()=>Apply(f,O("color",rgb,"brightness",80)),"strict static RGB schema");Check(f.Queries.Count==0&&f.Writes.Count==0,"RGB schema before native delegates");}
        var extra=Value();extra["effect"]=0;Reject(()=>Apply(new Fake(),extra),"no raw0 request or unknown fields");
        foreach(int pid in new[]{6906,7488,7490,0}){var f=new Fake();f.Device.Pid=(ushort)pid;Reject(()=>Apply(f),"no related headset inheritance");Check(f.Queries.Count==0&&f.Writes.Count==0,"unknown PID rejected before I/O");}
        foreach(string wrong in new[]{"page","usage","report","receiver","inputSize","outputSize"}){var f=new Fake();if(wrong=="page")f.Device.Page=0xFF01;if(wrong=="usage")f.Device.Usage=2;if(wrong=="report")f.Device.OutputReports=new byte[]{3};if(wrong=="receiver")f.Device.ReceiverPid=6862;if(wrong=="inputSize")f.Device.InputLength=9;if(wrong=="outputSize")f.Device.OutputLength=9;Reject(()=>Apply(f),"exact physical collection and report");Check(f.Queries.Count==0&&f.Writes.Count==0,"wrong collection no I/O");}
        foreach(string failure in new[]{"rejectEnable","partialEnable","throwEnable","recipeAtEnable","ownerAtEnable","disconnect","swapIdentity","rejectConfig","partialConfig","throwConfig","wrongColor","wrongBrightness","wrongMode","ledReadback"}){var f=new Fake();bool second=failure=="rejectConfig"||failure=="partialConfig"||failure=="throwConfig"||failure=="wrongColor"||failure=="wrongBrightness"||failure=="wrongMode";
            if(failure=="rejectEnable")f.RejectStep=0;if(failure=="partialEnable")f.FailStep=0;if(failure=="throwEnable")f.ThrowStep=0;if(failure=="recipeAtEnable")f.ChangeRecipeAtEnable=true;if(failure=="ownerAtEnable")f.ChangeOwner=true;if(failure=="disconnect")f.Disconnect=true;if(failure=="swapIdentity")f.SwapIdentity=true;if(failure=="rejectConfig")f.RejectStep=1;if(failure=="partialConfig")f.FailStep=1;if(failure=="throwConfig")f.ThrowStep=1;if(failure=="wrongColor")f.WrongColor=true;if(failure=="wrongBrightness")f.WrongBrightness=true;if(failure=="wrongMode")f.WrongMode=true;if(failure=="ledReadback")f.DisableLed=true;
            var result=Apply(f);Check(!(bool)result["writeConfirmed"],"failed compound never confirms "+failure);Check(f.Writes.Count==(second?2:1),"stop subsequent step "+failure);Check(GearLinkWorker.Text(result,"appliedState")== (second?"partial":"unconfirmed"),"honest partial phase result "+failure);Check(!f.Writes.Any(p=>p[1]==51||p[1]==16&&p[4]==0),"no blind ownership or LED rollback "+failure);if(failure.StartsWith("throw"))Check(!Snapshot(result).ContainsKey("lightingEffectCode")&&!Snapshot(result).ContainsKey("color"),"output exception invalidates prior current values");}
        var noAck=new Fake{NoAck=true};Check((bool)Apply(noAck)["writeConfirmed"],"complete independent readback can confirm despite missing ACK");
        var already=new Fake{Mode=1,Led=1,Brightness=80,Rgb=new[]{10,20,30}};var noOp=Apply(already,null,true);Check((bool)noOp["writeConfirmed"]&&!(bool)noOp["writeAttempted"]&&already.Writes.Count==0,"exact same observed static value is a no-output success");
        var guarded=new Fake();Reject(()=>Apply(guarded,null,true),"changed value refused by readonly guard");Check(guarded.Writes.Count==0,"readonly guard no output");
        var onlyEnable=new Fake{Mode=1,Led=0,Brightness=80,Rgb=new[]{10,20,30}};Check((bool)Apply(onlyEnable)["writeConfirmed"]&&onlyEnable.Writes.Count==1&&onlyEnable.Writes[0][1]==16,"already desired recipe only enables LEDs");
        var budget=new Fake();int calls=0;var bounded=Apply(budget,null,false,()=>calls++==0?0:16000);Check(GearLinkWorker.Text(bounded,"appliedState")=="partial"&&budget.Writes.Count==1,"deadline reserves each full readback before next output");budget=new Fake();bounded=Apply(budget,null,false,()=>16000);Check(!(bool)bounded["writeAttempted"]&&budget.Writes.Count==0&&GearLinkWorker.Text(bounded,"appliedState")=="unconfirmed","expired budget sends no output");
        var mutated=new Fake{MutateRequest=true};var request=Value();mutated.Request=request;var frozen=Apply(mutated,request);Check((bool)frozen["writeConfirmed"]&&mutated.Writes.Last().SequenceEqual(new byte[]{81,40,0,0,1,80,10,20,30}),"submitted value/plan immutable across callbacks");
        foreach(byte[] p in new[]{new byte[]{81,51,0,0,0},new byte[]{81,16,0,0,0},new byte[]{81,40,0,0,0,80,1,2,3},new byte[]{81,40,0,0,1,101,1,2,3},new byte[]{81,40,1,0,1,80,1,2,3}})Check(!GearLinkWorker.IsHeadsetStaticLightingWrite(p),"fixed compound transport rejects unsupported writes");
        foreach(string kind in new[]{"mouse","keyboard","unknown","headset"})foreach(string op in new[]{"lightingRead","lightingSet","set","read","scan","pair"})Check(GearLinkWorker.HeadsetLightingOperation(kind,op,"staticLighting")== (kind=="headset"&&(op=="lightingRead"||op=="lightingSet"||op=="set")),"exact operation routing");Check(!GearLinkWorker.HeadsetLightingOperation("headset","set","auraEnabled"),"existing Aura setting does not enter static compound");
        var packet=new byte[]{81,40,0,0,1,80,10,20,30};var legacyError=new byte[]{204,81,40,0,0,255,170};Check(GearLinkWorker.LegacyHeadsetErrorResponse(7489,204,packet,legacyError,7),"exact legacy embedded FF AA recognized");Check(!GearLinkWorker.LegacyHeadsetErrorResponse(6906,204,packet,legacyError,7),"other headset not inferred");Check(!GearLinkWorker.LegacyHeadsetErrorResponse(7489,3,packet,legacyError,7),"other report cannot reject pending command");Check(!GearLinkWorker.LegacyHeadsetErrorResponse(7489,204,packet,legacyError,6),"short embedded error cannot read missing byte");legacyError[2]=16;Check(!GearLinkWorker.LegacyHeadsetErrorResponse(7489,204,packet,legacyError,7),"another header's error cannot reject this request");legacyError[2]=40;
        int transfers=0;var rejected=GearLinkWorker.SendSettingAndAwaitResponse(7489,204,packet,65,65,(write,buffer,budgetMs)=>{transfers++;if(write)return buffer.Length;Array.Copy(legacyError,buffer,legacyError.Length);return legacyError.Length;});Check(rejected.OutputCompleted&&rejected.Rejected&&!rejected.Acknowledged&&transfers==2,"real receipt parser rejects legacy error before ACK");
    }
}
